inline const unsigned char* branch(const unsigned char* p,size_t displacement,size_t length){
    int32_t value{};std::memcpy(&value,p+displacement,4);
    return reinterpret_cast<const unsigned char*>(reinterpret_cast<uintptr_t>(p)+length+static_cast<int64_t>(value));
}
inline bool boundary(const unsigned char* p,size_t length,unsigned char* base,size_t size){
    auto nt=reinterpret_cast<IMAGE_NT_HEADERS64*>(base+reinterpret_cast<IMAGE_DOS_HEADER*>(base)->e_lfanew);
    auto directory=nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXCEPTION];
    if(directory.VirtualAddress>=size||directory.Size>size-directory.VirtualAddress||directory.Size%sizeof(RUNTIME_FUNCTION))return false;
    auto entries=reinterpret_cast<RUNTIME_FUNCTION*>(base+directory.VirtualAddress);
    auto rva=static_cast<DWORD>(p-base);size_t low=0,high=directory.Size/sizeof(RUNTIME_FUNCTION);
    while(low<high){auto mid=low+(high-low)/2;if(entries[mid].BeginAddress<rva)low=mid+1;else high=mid;}
    return low<directory.Size/sizeof(RUNTIME_FUNCTION)&&entries[low].BeginAddress==rva&&entries[low].EndAddress-rva==length;
}
template<size_t N>
inline bool linked(const unsigned char* p,const std::array<unsigned char,N>& code,const std::array<unsigned char,N>& mask,unsigned char* base,size_t size){
    return executable(p,N,base,size)&&matches(p,code,mask);
}
inline bool weaponDependencies(const unsigned char* p,unsigned char* base,size_t size){
    auto cold=branch(p+142,2,6),transform=branch(p+199,1,5),scale=branch(p+236,1,5);
    return boundary(p,weaponCode.size(),base,size)&&linked(cold,weaponColdCode,weaponColdMask,base,size)&&branch(cold+17,1,5)==p+155&&
        linked(transform,transformCode,transformMask,base,size)&&linked(scale,scaleCode,scaleMask,base,size)&&branch(p+273,1,5)==scale;
}
inline bool scabbardDependencies(const unsigned char* p,unsigned char* base,size_t size){
    auto cold=branch(p+128,2,6),transform=branch(p+184,1,5),scale=branch(p+234,1,5);
    return boundary(p,scabbardCode.size(),base,size)&&linked(cold,scabbardColdCode,scabbardColdMask,base,size)&&branch(cold+13,1,5)==p+141&&
        linked(transform,transformCode,transformMask,base,size)&&linked(scale,scaleCode,scaleMask,base,size);
}
inline std::array<void*,4> resolve(std::wstring& error){
    std::array<void*,4> result{};
    result[0]=NativeContract::resolveCode(weaponCode,weaponMask,weaponDependencies,error);if(!result[0])return {};
    result[1]=NativeContract::resolveCode(weaponVisibilityCode,weaponVisibilityMask,[](auto* p,auto* b,size_t s){return boundary(p,weaponVisibilityCode.size(),b,s);},error);if(!result[1])return {};
    result[2]=NativeContract::resolveCode(scabbardCode,scabbardMask,scabbardDependencies,error);if(!result[2])return {};
    result[3]=NativeContract::resolveCode(scabbardVisibilityCode,scabbardVisibilityMask,[](auto* p,auto* b,size_t s){return boundary(p,scabbardVisibilityCode.size(),b,s);},error);if(!result[3])return {};
    return result;
}
inline constexpr size_t interfaceOffset=0xbc0,weaponOffset=0xcb0,scabbardOffset=0xcb8;
inline bool interfaceMatches(void* pawn,size_t objectSize,size_t weapon,size_t scabbard,const std::array<void*,4>& targets){
    if(!pawn||!targets[0]||!targets[1]||!targets[2]||!targets[3]||weapon!=weaponOffset||scabbard!=scabbardOffset||objectSize<scabbardOffset+sizeof(void*))return false;
    void** table{};std::memcpy(&table,static_cast<unsigned char*>(pawn)+interfaceOffset,sizeof(table));
    MEMORY_BASIC_INFORMATION m{};auto at=reinterpret_cast<uintptr_t>(table);
    if(!VirtualQuery(table,&m,sizeof(m))||m.State!=MEM_COMMIT||m.Protect&(PAGE_GUARD|PAGE_NOACCESS)||at<reinterpret_cast<uintptr_t>(m.BaseAddress)||m.RegionSize<6*sizeof(void*)||at-reinterpret_cast<uintptr_t>(m.BaseAddress)>m.RegionSize-6*sizeof(void*))return false;
    for(size_t i=0;i<4;++i)if(table[i+2]!=targets[i])return false;
    return true;
}
